body .callout[data-callout*="teaparty"]  {
    --callout-icon: none;
	color: var(--lw);
	background-image: var(--gdj-teaparty);
	background-size: 100% auto;
	background-position: 50% 0%;
	background-repeat: repeat;
}

.nborder-teaparty {
	border-style: solid;
	border-width: 10px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-teaparty) 20;
}

.nborder-teaparty-layer { 
	border-style: solid;
	border-width: 1px;
	border-color: color-mix(in srgb, white, transparent 70%);
	border-image: var(--gdj-teaparty);
	border-image-width: auto;
	border-image-outset: 0 0 600 0;
	border-image-repeat: repeat;
}

.nhr-teaparty {
	--hr-svg: var(--gdj-teaparty);
}

.nbg-stamp-teaparty {
	--stamp-svg: var(--gdj-teaparty);
}

.nmask-teaparty {
	-webkit-mask-image: var(--gdj-teaparty), radial-gradient(black 50%, color-mix(in srgb, black, transparent 65%) 70%, color-mix(in srgb, black, transparent 100%) 90%);
}
.nmask-teaparty-less {
	-webkit-mask-image: var(--gdj-teaparty), radial-gradient(black 50%, color-mix(in srgb, black, transparent 50%) 70%);
}
.nmask-teaparty-fade {
	-webkit-mask-image: var(--gdj-teaparty), linear-gradient(black 65%, transparent 90%);
}
.nmask-teaparty-fademore {
	-webkit-mask-image: var(--gdj-teaparty), linear-gradient(black 35%, transparent 65%);
}
.nmask-teaparty-simple {
	-webkit-mask-image: var(--gdj-teaparty), linear-gradient(color-mix(in srgb, black, transparent 25%) 25%, color-mix(in srgb, black, transparent 50%) 75%);
}